public class TextBuffer_expandCurrentSegment_TriageGen2Test {

    private TextBuffer textBuffer;
    private static final int MAX_SEGMENT_LEN = 1024; // Assuming standard Jackson constant value

    @Before
    public void setUp() {
        // BufferRecycler is internal, passing null is usually fine for unit testing logic 
        // if the constructor allows or if we mock it. 
        // Given the context, we instantiate via constructor.
        textBuffer = new TextBuffer(null);
    }

    /**
     * Helper to inject a specific char array into the private _currentSegment field 
     * to control the state for testing expansion logic.
     */
    private void setPrivateCurrentSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Helper to get the private _currentSegment field.
     */
    private char[] getPrivateCurrentSegment() throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        return (char[]) field.get(textBuffer);
    }

    @Test
    public void testExpandCurrentSegment_NormalGrowth() throws Exception {
        // Initial state: length 10
        char[] initial = new char[10];
        setPrivateCurrentSegment(initial);

        // Expected: len + (len >> 1) = 10 + 5 = 15
        char[] expanded = textBuffer.expandCurrentSegment();

        Assert.assertEquals(15, expanded.length);
        Assert.assertEquals(15, getPrivateCurrentSegment().length);
        // Ensure identity/content is preserved (Arrays.copyOf)
        Assert.assertSame(expanded, getPrivateCurrentSegment());
    }








}

